/* Series glossary schema v1: ko, en, abbr, def, chapters[]; optional category, related, audio, examples, stage.
   This is the source of truth for both the glossary page and prose tooltips. */
window.BOOK_GLOSSARY = {
  version: 1,
  terms: [
    {"ko":"배수량","en":"Displacement","abbr":"Δ","def":"떠 있는 배가 밀어낸 물의 질량(톤). 부력과 무게가 평형이므로 화물·연료를 포함한 배 전체의 질량과 같다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"배수 용적","en":"Volume of displacement","abbr":"∇","def":"수면 아래 잠긴 선체의 부피(m³). 여기에 물의 밀도를 곱하면 배수량이 된다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"경하중량","en":"Lightweight (lightship)","abbr":"LWT","def":"선체·기관·의장품 등 배 자체의 질량. 화물·연료·청수·선원·식량을 싣지 않은 빈 배의 배수량이다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"흘수","en":"Draft (draught)","abbr":"T","def":"흘수선에서 용골 아랫면까지의 수직 거리. 선수·선미·중앙의 흘수 표시(draft mark)로 읽어 트림과 배수량을 구한다.","chapters":["overview"],"category":"S"},
    {"ko":"흘수선","en":"Waterline","abbr":"WL","def":"선체 표면과 수면이 만나는 선. 설계 기준이 되는 만재 상태의 흘수선을 설계 흘수선(DWL)이라 한다.","chapters":["overview"],"category":"S"},
    {"ko":"건현","en":"Freeboard","abbr":"f","def":"선체 중앙 선측에서 흘수선부터 건현 갑판 윗면까지의 수직 거리. 예비 부력과 갑판 침수 여유를 나타낸다.","chapters":["overview"],"category":"S"},
    {"ko":"형심","en":"Moulded depth","abbr":"D","def":"선체 중앙에서 기선(용골 상면)부터 건현 갑판 보 윗면까지 선측에서 잰 높이. 외판 두께를 뺀 형(moulded) 치수다.","chapters":["overview"],"category":"S"},
    {"ko":"형폭","en":"Moulded breadth","abbr":"B","def":"외판 안쪽 형 표면 사이에서 잰 선체의 최대 폭. 파나마 운하처럼 통과 폭 제한이 있는 곳에서 결정적인 치수다.","chapters":["overview"],"category":"S"},
    {"ko":"전장","en":"Length overall","abbr":"LOA","def":"선수 끝에서 선미 끝까지의 최대 길이. 부두 길이, 도크 크기, 운하·갑문 통과 조건에 쓰인다.","chapters":["overview"],"category":"S"},
    {"ko":"수선간장","en":"Length between perpendiculars","abbr":"Lpp","def":"선미 수선(AP)과 선수 수선(FP) 사이의 거리. 선형 계수, 저항, 구조 규칙 계산의 기준 길이다.","chapters":["overview"],"category":"S"},
    {"ko":"선미 수선","en":"Aft perpendicular","abbr":"AP","def":"보통 타두재 중심을 지나는 수직선. 수선간장의 뒤쪽 끝이다.","chapters":["overview"],"category":"S"},
    {"ko":"선수 수선","en":"Forward perpendicular","abbr":"FP","def":"설계 흘수선이 선수재 앞면과 만나는 점을 지나는 수직선. 수선간장의 앞쪽 끝이다.","chapters":["overview"],"category":"S"},
    {"ko":"기선","en":"Baseline","abbr":"K","def":"용골 상면을 지나는 수평 기준선. KB·KG·KM 등 모든 높이를 여기서 잰다.","chapters":["overview"],"category":"S"},
    {"ko":"중심선","en":"Centreline","abbr":"CL","def":"선체를 좌우 대칭으로 나누는 세로 기준면. 횡방향 무게중심(TCG)을 이 선에서 잰다.","chapters":["overview"],"category":"S"},
    {"ko":"블록 계수","en":"Block coefficient","abbr":"Cb","def":"배수 용적을 L·B·T 직육면체 부피로 나눈 값. 날씬한 컨테이너선 약 0.6~0.7, 비대한 VLCC 약 0.8~0.85다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"주형 계수","en":"Prismatic coefficient","abbr":"Cp","def":"배수 용적을 중앙 단면적 × 길이로 나눈 값(Cp = Cb/Cm). 길이 방향 부피 분포를 나타내며 조파 저항과 관계가 깊다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"중앙단면 계수","en":"Midship section coefficient","abbr":"Cm","def":"중앙 단면의 잠긴 면적을 B·T로 나눈 값. 빌지가 작은 대형 상선은 0.98~0.99에 이른다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"수선면 계수","en":"Waterplane area coefficient","abbr":"Cwp","def":"수선면 면적을 L·B로 나눈 값. 클수록 TPC와 횡 메타센터 반지름 BM이 커진다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"매 센티미터 배수톤","en":"Tonnes per centimetre immersion","abbr":"TPC","def":"평균 흘수를 1 cm 바꾸는 데 필요한 질량. TPC = Aw·ρ/100(Aw: 수선면 면적 m²)이며 적하 계산에 쓴다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"매 센티미터 트림 모멘트","en":"Moment to change trim one centimetre","abbr":"MCT","def":"트림을 1 cm 바꾸는 데 필요한 모멘트(t·m/cm). 대략 Δ·GM_L/(100·Lpp)이다.","chapters":["trim"],"category":"S"},
    {"ko":"부면심","en":"Longitudinal centre of flotation","abbr":"LCF","def":"수선면 면적의 길이 방향 도심. 작은 트림에서 배는 이 점을 지나는 가로축을 중심으로 기운다.","chapters":["trim"],"category":"S"},
    {"ko":"부심","en":"Centre of buoyancy","abbr":"B","def":"잠긴 부피의 도심으로, 부력이 작용하는 점이다. 배가 기울면 잠긴 모양이 바뀌어 낮은 쪽으로 이동한다.","chapters":["stability"],"category":"S"},
    {"ko":"종방향 부심 위치","en":"Longitudinal centre of buoyancy","abbr":"LCB","def":"부심의 길이 방향 위치. 선형의 앞뒤 부피 배분을 나타내며 비대선일수록 앞쪽에 둔다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"무게중심","en":"Centre of gravity","abbr":"G","def":"배 전체 질량의 중심. 적재 상태에 따라 변하며, 높이 KG가 복원성을 좌우한다.","chapters":["stability"],"category":"S"},
    {"ko":"종방향 무게중심","en":"Longitudinal centre of gravity","abbr":"LCG","def":"무게중심의 길이 방향 위치. LCB와 수직선이 어긋나면 일치할 때까지 배가 트림한다.","chapters":["trim"],"category":"S"},
    {"ko":"KB","en":"Height of centre of buoyancy above keel","abbr":"KB","def":"용골에서 부심까지의 높이. 상자형 단면에서는 흘수의 절반, 일반 선형은 약 0.52~0.55 T다.","chapters":["stability"],"category":"S"},
    {"ko":"BM","en":"Transverse metacentric radius","abbr":"BM","def":"부심에서 메타센터까지의 거리. BM = I_T/∇이며 폭의 세제곱에 비례하므로 폭이 넓은 배일수록 크다.","chapters":["stability"],"category":"S"},
    {"ko":"KM","en":"Height of metacentre above keel","abbr":"KM","def":"용골에서 메타센터까지의 높이(KB + BM). 흘수만으로 정해지는 선형의 성질로, 유체정역학 곡선에서 읽는다.","chapters":["stability"],"category":"S"},
    {"ko":"KG","en":"Height of centre of gravity above keel","abbr":"KG","def":"용골에서 무게중심까지의 높이. 화물을 높이 쌓을수록 커지며, 경사 시험으로 경하 상태의 값을 확정한다.","chapters":["stability"],"category":"S"},
    {"ko":"메타센터 높이","en":"Metacentric height","abbr":"GM","def":"무게중심에서 메타센터까지의 높이(GM = KM − KG). 초기 복원성의 척도이며 양수여야 작은 경사에서 다시 일어선다.","chapters":["stability"],"category":"S"},
    {"ko":"복원정","en":"Righting lever","abbr":"GZ","def":"경사 상태에서 중력과 부력의 작용선 사이 수평 거리. 복원 모멘트는 Δ·g·GZ이고 작은 각에서 GZ ≈ GM·sinφ다.","chapters":["stability"],"category":"S"},
    {"ko":"메타센터","en":"Metacentre","abbr":"M","def":"작은 경사에서 부력 작용선이 중심선과 만나는 점. M이 G보다 위에 있으면 배는 안정하다.","chapters":["stability"],"category":"S"},
    {"ko":"복원성 곡선","en":"Righting lever curve (GZ curve)","abbr":"","def":"경사각에 따른 GZ를 그린 곡선. 최대 GZ, 그 각도, 곡선 아래 면적, 소실각이 IMO 복원성 기준의 판정 항목이다.","chapters":["stability"],"category":"S"},
    {"ko":"복원력 소실각","en":"Angle of vanishing stability","abbr":"AVS","def":"GZ가 다시 0이 되는 경사각. 이 각을 넘으면 배는 스스로 일어서지 못하고 전복한다.","chapters":["stability"],"category":"S"},
    {"ko":"자유수면 효과","en":"Free surface effect","abbr":"FSE","def":"부분 적재 탱크의 액체가 경사 쪽으로 쏠려 무게중심이 올라간 것과 같은 효과. GM 감소량은 ρ_l·i/Δ로 탱크 폭의 세제곱에 비례한다.","chapters":["trim"],"category":"S"},
    {"ko":"롤 주기","en":"Roll period","abbr":"Tφ","def":"횡동요 한 번의 고유 주기. 근사적으로 Tφ ≈ 2π·k/√(g·GM)(k: 횡 회전 반경 ≈ 0.35~0.4 B)이라 주기로 GM을 추정할 수 있다.","chapters":["stability"],"category":"S"},
    {"ko":"경사 시험","en":"Inclining experiment","abbr":"","def":"무게를 아는 추를 옆으로 옮겨 경사각을 재고 GM = w·d/(Δ·tanφ)로 GM과 KG를 구하는 시험. 건조 직후 반드시 한다.","chapters":["stability"],"category":"S"},
    {"ko":"트림","en":"Trim","abbr":"t","def":"선미 흘수와 선수 흘수의 차. 선미가 더 깊으면 선미 트림(by the stern), 선수가 더 깊으면 선수 트림이다.","chapters":["trim"],"category":"S"},
    {"ko":"횡경사","en":"List / heel","abbr":"","def":"list는 화물·탱크의 좌우 불균형으로 생기는 정적인 경사, heel은 바람·선회·파도 같은 외력에 의한 일시적 경사를 가리킨다.","chapters":["trim"],"category":"S"},
    {"ko":"밸러스트","en":"Ballast","abbr":"","def":"흘수·트림·복원성을 맞추려고 싣는 무게. 대부분 해수를 밸러스트 탱크에 채우며, 외래종 이동을 막기 위해 처리 장치(BWMS)가 의무다.","chapters":["trim"],"category":"S"},
    {"ko":"유체정역학 곡선","en":"Hydrostatic curves","abbr":"","def":"흘수에 따른 배수량, TPC, MCT, LCB, LCF, KB, KM 등을 한 장에 그린 곡선. 적하 계산의 기본 자료다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"만재흘수선","en":"Load line (Plimsoll mark)","abbr":"","def":"계절·해역·물의 종류별 최대 허용 흘수를 선측에 표시한 선. 하기(S), 동기(W), 열대(T), 담수(F) 등의 눈금이 있다.","chapters":["buoyancy"],"category":"S"},
    {"ko":"투과율","en":"Permeability","abbr":"μ","def":"침수된 구획의 부피 중 물이 실제로 찰 수 있는 비율. 거주구 0.95, 기관실 0.85 정도가 대표값이다.","chapters":["damage"],"category":"S"},
    {"ko":"가항 길이","en":"Floodable length","abbr":"","def":"어느 위치를 중심으로 그 길이만큼의 구획이 침수돼도 마진 라인이 잠기지 않는 최대 길이. 결정론적 구획 설계의 기준이었다.","chapters":["damage"],"category":"S"},
    {"ko":"마진 라인","en":"Margin line","abbr":"","def":"격벽 갑판 윗면에서 선측으로 76 mm 아래에 그은 가상의 선. 침수 후 수면이 이 선을 넘지 않아야 한다.","chapters":["damage"],"category":"S"},
    {"ko":"격벽 갑판","en":"Bulkhead deck","abbr":"","def":"수밀 횡격벽이 올라와 닿는 가장 위의 갑판. 침수 계산에서 물이 넘어 다른 구획으로 번지지 않는 경계다.","chapters":["damage"],"category":"S"},
    {"ko":"수밀 격벽","en":"Watertight bulkhead","abbr":"","def":"선체를 길이 방향으로 나누는 물이 새지 않는 벽. 한 구획이 침수돼도 나머지가 부력을 지키게 한다.","chapters":["damage"],"category":"S"},
    {"ko":"이중 선저","en":"Double bottom","abbr":"DB","def":"선저 외판 위에 내저판을 한 겹 더 둔 구조. 좌초 시 침수를 막고 그 사이 공간을 연료·밸러스트 탱크로 쓴다.","chapters":["damage"],"category":"S"},
    {"ko":"이중 선체","en":"Double hull","abbr":"","def":"선측과 선저를 모두 두 겹으로 만든 구조. 1990년대 이후 MARPOL에 따라 유조선에 의무화되었다.","chapters":["damage"],"category":"S"},
    {"ko":"구획 지수","en":"Subdivision index (A, R)","abbr":"A / R","def":"확률론적 손상 복원성에서 손상 위치·크기별 생존 확률을 가중 합산한 달성 지수 A. 선박 길이와 인원으로 정한 요구 지수 R 이상이어야 한다.","chapters":["damage"],"category":"S"},
    {"ko":"손상 복원성","en":"Damage stability","abbr":"","def":"선체가 파손되어 일부 구획이 침수된 뒤에도 배가 떠서 바로 서 있을 수 있는 능력.","chapters":["damage"],"category":"S"},
    {"ko":"교차 침수","en":"Cross-flooding","abbr":"","def":"한쪽 현의 침수로 생긴 경사를 줄이려고 반대 현의 구획에 일부러 물을 넣는 것. 비대칭 침수 대책이다.","chapters":["damage"],"category":"S"},
    {"ko":"레이놀즈수","en":"Reynolds number","abbr":"Re","def":"관성력과 점성력의 비 VL/ν. 실선은 약 10⁹, 모형은 10⁶~10⁷ 정도로 마찰 저항 계수를 정한다.","chapters":["resistance"],"category":"R"},
    {"ko":"프루드수","en":"Froude number","abbr":"Fn","def":"속도와 길이로 만든 무차원수 V/√(gL). 조파 저항과 파형을 정하며, 모형 시험은 프루드수를 맞춰 한다.","chapters":["resistance"],"category":"R"},
    {"ko":"마찰 저항","en":"Frictional resistance","abbr":"RF","def":"물의 점성 때문에 선체 표면에 생기는 접선 방향 저항. 저속 대형선 전체 저항의 70~90 %를 차지한다. ITTC-1957 식 CF = 0.075/(log Re − 2)²로 추정한다.","chapters":["resistance"],"category":"R"},
    {"ko":"조파 저항","en":"Wave-making resistance","abbr":"RW","def":"선체가 파도를 만들며 잃는 에너지로 생기는 저항. 프루드수에 따라 급격히 커지고 선수·선미 파의 간섭으로 혹과 골이 생긴다.","chapters":["resistance"],"category":"R"},
    {"ko":"형상 계수","en":"Form factor","abbr":"1+k","def":"3차원 선체의 점성 저항이 같은 길이 평판의 마찰 저항보다 몇 배인지 나타내는 계수. 비대선일수록 크다.","chapters":["resistance"],"category":"R"},
    {"ko":"잉여 저항","en":"Residuary resistance","abbr":"RR","def":"전체 저항에서 평판 마찰 저항을 뺀 나머지. 주로 조파 저항이며 프루드 상사로 실선에 옮긴다.","chapters":["resistance"],"category":"R"},
    {"ko":"켈빈 파형","en":"Kelvin wave pattern","abbr":"","def":"움직이는 압력점 뒤에 생기는 발산파·횡파의 무늬. 심해에서는 속도와 상관없이 항적 중심선과 약 19.5°의 쐐기 안에 갇힌다.","chapters":["resistance"],"category":"R"},
    {"ko":"선수 벌브","en":"Bulbous bow","abbr":"","def":"선수 아래에 튀어나온 둥근 부분. 선수파와 위상이 반대인 파를 만들어 설계 속도 근처에서 조파 저항을 줄인다.","chapters":["resistance"],"category":"R"},
    {"ko":"모형 시험","en":"Model test (towing tank)","abbr":"","def":"축척 모형을 예인 수조에서 끌어 저항·자항·내항 성능을 재는 시험. 프루드 상사로 실선 성능을 추정한다.","chapters":["resistance"],"category":"R"},
    {"ko":"유효 동력","en":"Effective power","abbr":"PE","def":"선체를 그 속도로 끄는 데 필요한 동력 PE = R·V. 프로펠러가 실제로 내야 하는 동력보다 작다.","chapters":["resistance"],"category":"R"},
    {"ko":"전달 동력","en":"Delivered power","abbr":"PD","def":"축계를 거쳐 프로펠러에 실제로 전달되는 동력. PE/PD가 준추진 효율이다.","chapters":["propulsion"],"category":"R"},
    {"ko":"제동 동력","en":"Brake power","abbr":"PB","def":"엔진 출력축에서 나오는 동력. 축계·감속기 손실만큼 전달 동력보다 크다.","chapters":["propulsion"],"category":"R"},
    {"ko":"반류","en":"Wake","abbr":"w","def":"선체 뒤에 끌려가는 느린 물의 흐름. 프로펠러 유입 속도 VA = V(1 − w)로 나타내며 비대선일수록 크다.","chapters":["propulsion"],"category":"R"},
    {"ko":"추력 감소","en":"Thrust deduction","abbr":"t","def":"프로펠러가 선체 뒤 물을 빨아들여 선미 압력을 낮추면서 저항이 늘어나는 효과. R = T(1 − t).","chapters":["propulsion"],"category":"R"},
    {"ko":"선체 효율","en":"Hull efficiency","abbr":"ηH","def":"ηH = (1 − t)/(1 − w). 반류 덕분에 1보다 클 수 있으며 단일 스크루 비대선은 약 1.1~1.3이다.","chapters":["propulsion"],"category":"R"},
    {"ko":"단독 효율","en":"Open-water efficiency","abbr":"η0","def":"균일한 흐름 속에서 프로펠러만의 효율 η0 = J·KT/(2π·KQ). 대형 상선 프로펠러는 대표적으로 0.5~0.7이다.","chapters":["propeller"],"category":"R"},
    {"ko":"상대 회전 효율","en":"Relative rotative efficiency","abbr":"ηR","def":"같은 추력에서 단독 시험과 선체 뒤 사이의 토크 차를 보정하는 효율. 보통 0.98~1.05로 1에 가깝다.","chapters":["propulsion"],"category":"R"},
    {"ko":"준추진 효율","en":"Quasi-propulsive efficiency","abbr":"ηD","def":"ηD = ηH·η0·ηR = PE/PD. 선체와 프로펠러의 상호작용을 포함한 추진 효율이다.","chapters":["propulsion"],"category":"R"},
    {"ko":"전진 계수","en":"Advance ratio","abbr":"J","def":"J = VA/(n·D). 프로펠러가 한 바퀴 돌 때 직경의 몇 배만큼 나아가는지 나타내며 날개 받음각을 정한다.","chapters":["propeller"],"category":"R"},
    {"ko":"추력 계수","en":"Thrust coefficient","abbr":"KT","def":"KT = T/(ρ·n²·D⁴). J가 커질수록 줄어든다.","chapters":["propeller"],"category":"R"},
    {"ko":"토크 계수","en":"Torque coefficient","abbr":"KQ","def":"KQ = Q/(ρ·n²·D⁵). KT와 함께 프로펠러 단독 특성 곡선을 이룬다.","chapters":["propeller"],"category":"R"},
    {"ko":"피치","en":"Pitch","abbr":"P","def":"프로펠러가 단단한 너트 속에서 한 바퀴 돌 때 나아갈 거리. 직경으로 나눈 피치비 P/D는 대표적으로 0.6~1.2다.","chapters":["propeller"],"category":"R"},
    {"ko":"슬립","en":"Slip","abbr":"","def":"피치로 계산한 이론 전진 거리와 실제 전진 거리의 차를 비율로 나타낸 것. 슬립이 있어야 날개가 받음각을 갖고 추력을 낸다.","chapters":["propeller"],"category":"R"},
    {"ko":"캐비테이션","en":"Cavitation","abbr":"","def":"날개 표면 압력이 증기압 아래로 떨어져 기포가 생기고 터지는 현상. 침식·소음·진동·추력 저하를 일으킨다.","chapters":["propeller"],"category":"R"},
    {"ko":"캐비테이션 수","en":"Cavitation number","abbr":"σ","def":"σ = (p0 − pv)/(½ρV²). 작을수록 캐비테이션이 잘 생긴다. 프로펠러가 얕게 잠기거나 회전이 빠를수록 작아진다.","chapters":["propeller"],"category":"R"},
    {"ko":"스큐","en":"Skew","abbr":"","def":"날개를 회전 반대 방향으로 휘게 한 정도. 날개 각 부분이 반류 골에 들어가는 시점을 엇갈리게 해 진동과 압력 변동을 줄인다.","chapters":["propeller"],"category":"R"},
    {"ko":"날개 면적비","en":"Expanded blade area ratio","abbr":"AE/A0","def":"펼친 날개 면적의 합을 프로펠러 원판 면적으로 나눈 값. 크면 캐비테이션에 강하지만 마찰 손실이 늘어난다.","chapters":["propeller"],"category":"R"},
    {"ko":"가변 피치 프로펠러","en":"Controllable pitch propeller","abbr":"CPP","def":"허브 안의 유압 기구로 날개 피치를 바꾸는 프로펠러. 엔진 회전수를 일정하게 두고 추력·후진을 조절할 수 있다.","chapters":["propeller"],"category":"R"},
    {"ko":"고정 피치 프로펠러","en":"Fixed pitch propeller","abbr":"FPP","def":"날개가 허브와 일체인 일반 프로펠러. 단순하고 효율이 좋으며 후진은 엔진 역회전으로 한다.","chapters":["propeller"],"category":"R"},
    {"ko":"덕트 프로펠러","en":"Ducted propeller (Kort nozzle)","abbr":"","def":"프로펠러 둘레에 날개 단면 모양의 링을 씌운 것. 저속·고부하에서 덕트 자체가 추력을 내 예인선·트롤선에 쓴다.","chapters":["propeller"],"category":"R"},
    {"ko":"포드 추진","en":"Podded propulsion","abbr":"","def":"전동기를 선체 밖 유선형 포드에 넣고 포드째 360° 돌려 추력 방향을 바꾸는 장치. 타가 필요 없고 조종성이 뛰어나다.","chapters":["electric"],"category":"R"},
    {"ko":"워터제트","en":"Waterjet","abbr":"","def":"선저에서 물을 빨아들여 펌프로 가속해 선미로 뿜는 추진 장치. 고속선에서 효율이 좋고 노즐 방향으로 조종한다.","chapters":["special"],"category":"R"},
    {"ko":"운동량 이론","en":"Momentum (actuator disk) theory","abbr":"","def":"프로펠러를 물을 가속하는 얇은 원판으로 본 이론. 추력 부하가 클수록 이상 효율의 상한이 낮아진다.","chapters":["propeller"],"category":"R"},
    {"ko":"최대 연속 출력","en":"Maximum continuous rating","abbr":"MCR","def":"엔진이 연속해서 낼 수 있는 최대 출력과 회전수. 엔진 선정과 프로펠러 설계의 기준점이다.","chapters":["propulsion"],"category":"R"},
    {"ko":"상용 출력","en":"Normal continuous rating","abbr":"NCR","def":"평소 항해에서 쓰는 출력. 대표적으로 MCR의 85~90 %로 잡는다.","chapters":["propulsion"],"category":"R"},
    {"ko":"해상 여유","en":"Sea margin","abbr":"","def":"바람·파도·선체 오손으로 늘어나는 동력을 위해 잔잔한 바다 기준 동력에 더해 두는 여유. 보통 15~25 %다.","chapters":["propulsion"],"category":"R"},
    {"ko":"엔진 여유","en":"Engine margin","abbr":"","def":"엔진을 MCR보다 낮게 운전하도록 남겨 두는 여유(보통 10~15 %). 정비 주기를 늘리고 마모를 줄인다.","chapters":["propulsion"],"category":"R"},
    {"ko":"라이트 러닝 마진","en":"Light running margin","abbr":"LRM","def":"신조 시 프로펠러를 조금 가볍게(회전이 높게) 설계해 두는 여유. 선체 오손·악천후로 무거워져도 엔진이 과부하되지 않게 한다.","chapters":["propulsion"],"category":"R"},
    {"ko":"프로펠러 법칙","en":"Propeller law","abbr":"","def":"고정 피치 프로펠러에서 동력이 회전수의 세제곱에 대략 비례한다는 관계. 엔진 운전점이 그리는 곡선이다.","chapters":["propulsion"],"category":"R"},
    {"ko":"선체 오손","en":"Hull fouling","abbr":"","def":"선체에 따개비·해조류가 붙어 표면이 거칠어지는 것. 마찰 저항을 수십 %까지 늘리며 방오 도료와 선체 청소로 막는다.","chapters":["resistance"],"category":"R"},
    {"ko":"저속 2행정 디젤","en":"Low-speed two-stroke diesel","abbr":"","def":"약 60~120 rpm으로 돌며 프로펠러에 직결되는 대형 상선의 주기관. 열효율이 50 %를 넘는 가장 효율 좋은 열기관 중 하나다.","chapters":["engine"],"category":"E"},
    {"ko":"중속 4행정 디젤","en":"Medium-speed four-stroke diesel","abbr":"","def":"약 400~1,000 rpm의 4행정 엔진. 발전기 구동이나 감속기를 통한 추진에 쓰이며 페리·크루즈·특수선에 많다.","chapters":["engine"],"category":"E"},
    {"ko":"크로스헤드","en":"Crosshead","abbr":"","def":"피스톤 로드와 커넥팅 로드 사이에서 가이드를 따라 미끄러지는 연결부. 측압을 대신 받아 피스톤·라이너 마모를 줄인다.","chapters":["engine"],"category":"E"},
    {"ko":"소기","en":"Scavenging","abbr":"","def":"연소가 끝난 배기가스를 신선한 공기로 밀어내고 실린더를 채우는 과정. 2행정 엔진의 핵심이다.","chapters":["engine"],"category":"E"},
    {"ko":"유니플로 소기","en":"Uniflow scavenging","abbr":"","def":"라이너 아래쪽 소기 포트로 들어온 공기가 위쪽 배기 밸브로 한 방향으로 빠져나가는 방식. 현대 대형 2행정 엔진의 표준이다.","chapters":["engine"],"category":"E"},
    {"ko":"과급기","en":"Turbocharger","abbr":"T/C","def":"배기가스로 터빈을 돌려 같은 축의 압축기로 흡기를 압축하는 장치. 같은 크기 엔진의 출력을 몇 배로 높인다.","chapters":["engine"],"category":"E"},
    {"ko":"소기 공기 냉각기","en":"Scavenge air cooler","abbr":"","def":"과급기로 압축되며 뜨거워진 공기를 식히는 열교환기. 공기 밀도를 높이고 NOx와 열부하를 줄인다.","chapters":["engine"],"category":"E"},
    {"ko":"연료 소비율","en":"Specific fuel oil consumption","abbr":"SFOC","def":"출력 1 kWh당 쓰는 연료량(g/kWh). 대형 2행정 엔진은 대표적으로 약 160~175 g/kWh다.","chapters":["engine"],"category":"E"},
    {"ko":"중유","en":"Heavy fuel oil","abbr":"HFO","def":"원유 정제 후 남은 점도 높은 잔사유. 값이 싸지만 가열·청정이 필요하고 황 함량이 높다.","chapters":["engine"],"category":"E"},
    {"ko":"초저유황유","en":"Very low sulphur fuel oil","abbr":"VLSFO","def":"황 함량 0.50 % 이하의 혼합 연료유. 2020년 IMO 황 상한 강화 이후 주력 연료가 되었다.","chapters":["engine"],"category":"E"},
    {"ko":"선박용 경유","en":"Marine gas oil","abbr":"MGO","def":"증류유 계열의 가벼운 연료. 황 함량이 낮아 배출규제해역과 발전기, 비상용으로 쓴다.","chapters":["engine"],"category":"E"},
    {"ko":"스크러버","en":"Exhaust gas scrubber","abbr":"EGCS","def":"배기가스를 해수나 알칼리 용액으로 씻어 SOx를 제거하는 장치. 고유황 HFO를 계속 쓸 수 있게 해 준다.","chapters":["engine"],"category":"E"},
    {"ko":"이중 연료 엔진","en":"Dual-fuel engine","abbr":"DF","def":"가스 연료(LNG 등)와 액체 연료를 모두 쓰는 엔진. 가스 모드에서는 소량의 파일럿 연료로 점화한다.","chapters":["engine"],"category":"E"},
    {"ko":"메탄 슬립","en":"Methane slip","abbr":"","def":"LNG 엔진에서 타지 않은 메탄이 배기로 빠져나가는 것. 메탄의 온실 효과가 커 LNG의 탄소 이점을 깎아 먹는다.","chapters":["engine"],"category":"E"},
    {"ko":"파일럿 연료","en":"Pilot fuel","abbr":"","def":"가스 모드 이중 연료 엔진에서 점화원으로 분사하는 소량의 액체 연료. 보통 전체 열량의 1~5 %다.","chapters":["engine"],"category":"E"},
    {"ko":"선택적 촉매 환원","en":"Selective catalytic reduction","abbr":"SCR","def":"요소수에서 나온 암모니아로 배기 속 NOx를 질소와 물로 바꾸는 촉매 장치. IMO NOx Tier III 대응 수단이다.","chapters":["engine"],"category":"E"},
    {"ko":"배기가스 재순환","en":"Exhaust gas recirculation","abbr":"EGR","def":"배기가스 일부를 흡기로 되돌려 연소 온도를 낮추는 방식. NOx 생성을 줄인다.","chapters":["engine"],"category":"E"},
    {"ko":"커먼레일","en":"Common rail","abbr":"","def":"고압 연료를 공용 배관에 저장해 두고 전자 제어로 분사 시기와 양을 자유롭게 정하는 방식. 저부하 연소와 매연 저감에 유리하다.","chapters":["engine"],"category":"E"},
    {"ko":"연료 청정기","en":"Fuel oil purifier","abbr":"","def":"원심 분리로 연료유 속 물과 고형 불순물(촉매 미분 등)을 걸러 내는 장치.","chapters":["engine"],"category":"E"},
    {"ko":"폐열 회수","en":"Waste heat recovery","abbr":"WHR","def":"배기가스 열로 증기를 만들어 터빈 발전이나 가열에 쓰는 장치. 엔진 출력의 수 %를 되찾는다.","chapters":["engine"],"category":"E"},
    {"ko":"추력 베어링","en":"Thrust bearing","abbr":"","def":"프로펠러 추력을 축에서 받아 선체로 전달하는 베어링. 이 베어링을 거쳐야 프로펠러가 배를 민다.","chapters":["engine"],"category":"E"},
    {"ko":"축계","en":"Shafting","abbr":"","def":"엔진에서 프로펠러까지 동력을 전달하는 축과 베어링, 선미관 밀봉 장치의 총칭.","chapters":["engine"],"category":"E"},
    {"ko":"분산 관계","en":"Dispersion relation","abbr":"","def":"파의 각주파수와 파수의 관계 ω² = gk·tanh(kh). 심해에서는 ω² = gk가 되어 긴 파일수록 빠르다.","chapters":["waves"],"category":"W"},
    {"ko":"위상 속도","en":"Phase velocity","abbr":"c","def":"파의 마루가 이동하는 속도 c = ω/k. 심해에서 c = gT/(2π) ≈ 1.56·T m/s다.","chapters":["waves"],"category":"W"},
    {"ko":"군속도","en":"Group velocity","abbr":"cg","def":"파군과 에너지가 이동하는 속도. 심해에서 위상 속도의 절반, 천해에서는 위상 속도와 같아진다.","chapters":["waves"],"category":"W"},
    {"ko":"파장","en":"Wavelength","abbr":"λ","def":"마루에서 다음 마루까지의 거리. 심해에서 λ = gT²/(2π) ≈ 1.56·T² m다.","chapters":["waves"],"category":"W"},
    {"ko":"유의파고","en":"Significant wave height","abbr":"Hs","def":"관측한 파고 중 높은 쪽 1/3의 평균. 눈으로 본 파고와 비슷하며 스펙트럼으로는 4√m0다.","chapters":["waves"],"category":"W"},
    {"ko":"파 스펙트럼","en":"Wave spectrum","abbr":"S(ω)","def":"불규칙한 바다를 주파수별 파 에너지로 나타낸 함수. 면적 m0가 수면 변위의 분산이다.","chapters":["waves"],"category":"W"},
    {"ko":"JONSWAP 스펙트럼","en":"JONSWAP spectrum","abbr":"","def":"북해 관측에서 나온 발달 중인 풍랑 스펙트럼. PM 스펙트럼에 첨두 증폭 계수 γ(보통 3.3)를 곱해 봉우리가 뾰족하다.","chapters":["waves"],"category":"W"},
    {"ko":"피어슨–모스코위츠 스펙트럼","en":"Pierson–Moskowitz spectrum","abbr":"PM","def":"바람이 충분히 오래, 멀리 불어 완전히 발달한 바다의 스펙트럼.","chapters":["waves"],"category":"W"},
    {"ko":"레일리 분포","en":"Rayleigh distribution","abbr":"","def":"좁은 대역 불규칙 파의 파고(진폭)가 따르는 확률 분포. 1,000개 파 중 최대 파고는 약 1.86 Hs다.","chapters":["waves"],"category":"W"},
    {"ko":"너울","en":"Swell","abbr":"","def":"바람이 불던 해역을 벗어나 멀리 전파된 주기가 긴 파. 둥글고 규칙적이며 수천 km를 간다.","chapters":["waves"],"category":"W"},
    {"ko":"풍랑","en":"Wind sea","abbr":"","def":"지금 부는 바람으로 만들어지는 파. 주기가 짧고 불규칙하며 바람 세기·지속 시간·취송 거리로 크기가 정해진다.","chapters":["waves"],"category":"W"},
    {"ko":"취송 거리","en":"Fetch","abbr":"","def":"바람이 일정한 방향으로 해면 위를 불어 온 거리. 길수록 파가 크게 발달한다.","chapters":["waves"],"category":"W"},
    {"ko":"천수 변형","en":"Wave shoaling","abbr":"","def":"파가 얕은 곳으로 들어오며 속도가 줄고 파고가 커지는 현상. 주기는 변하지 않는다.","chapters":["waves"],"category":"W"},
    {"ko":"굴절","en":"Wave refraction","abbr":"","def":"수심 변화로 파의 부분마다 속도가 달라 파봉선이 등심선과 나란해지도록 휘는 현상.","chapters":["waves"],"category":"W"},
    {"ko":"쇄파","en":"Wave breaking","abbr":"","def":"파가 너무 가팔라져 마루가 무너지는 현상. 심해에서는 파경사 H/λ가 약 1/7, 천해에서는 H가 수심의 약 0.78배를 넘으면 부서진다.","chapters":["waves"],"category":"W"},
    {"ko":"해상 상태","en":"Sea state","abbr":"SS","def":"바다의 거칠기를 유의파고로 0~9 단계로 나눈 등급(WMO). 보퍼트 풍력 계급과 함께 쓴다.","chapters":["waves"],"category":"W"},
    {"ko":"6자유도 운동","en":"Six degrees of freedom","abbr":"6-DOF","def":"강체인 배의 운동을 세 방향 병진(서지·스웨이·히브)과 세 축 회전(롤·피치·요)으로 나눈 것.","chapters":["seakeeping"],"category":"W"},
    {"ko":"서지","en":"Surge","abbr":"","def":"길이 방향(앞뒤) 병진 운동.","chapters":["seakeeping"],"category":"W"},
    {"ko":"스웨이","en":"Sway","abbr":"","def":"폭 방향(좌우) 병진 운동.","chapters":["seakeeping"],"category":"W"},
    {"ko":"히브","en":"Heave","abbr":"","def":"수직 방향(상하) 병진 운동. 수선면 면적이 복원력이 된다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"롤 운동","en":"Roll (횡동요)","abbr":"","def":"길이 방향 축을 중심으로 한 회전 운동. 감쇠가 작아 공진 시 매우 커질 수 있다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"피치 운동","en":"Pitch (종동요)","abbr":"","def":"폭 방향 축을 중심으로 선수와 선미가 오르내리는 회전 운동. 선수 쪽 가속도와 슬래밍을 일으킨다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"요 운동","en":"Yaw (선수동요)","abbr":"","def":"수직축을 중심으로 선수 방향이 좌우로 흔들리는 회전 운동. 복원력이 없어 타로 잡는다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"응답 진폭 연산자","en":"Response amplitude operator","abbr":"RAO","def":"규칙파 진폭 1당 배 운동의 진폭을 주파수별로 나타낸 전달 함수. 파 스펙트럼에 RAO²을 곱하면 응답 스펙트럼이 된다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"조우 주파수","en":"Encounter frequency","abbr":"ωe","def":"움직이는 배가 실제로 파를 만나는 주파수 ωe = ω − kU·cosμ. 선수파에서는 높아지고 추종파에서는 낮아진다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"부가 질량","en":"Added mass","abbr":"","def":"물체가 가속할 때 주변 물도 함께 가속해야 해서 질량이 늘어난 것처럼 보이는 효과. 히브에서는 선체 질량과 비슷한 크기가 되기도 한다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"방사 감쇠","en":"Radiation damping","abbr":"","def":"움직이는 선체가 파를 만들어 내보내며 에너지를 잃는 감쇠. 히브·피치에서는 크고 롤에서는 작다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"고유 주기","en":"Natural period","abbr":"","def":"외력 없이 스스로 진동할 때의 주기. 파의 조우 주기와 가까우면 공진으로 운동이 커진다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"슬래밍","en":"Slamming","abbr":"","def":"선저가 수면 밖으로 나왔다가 다시 들어가며 물을 세게 때리는 충격. 국부 손상과 선체 휘핑을 일으킨다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"그린 워터","en":"Green water","abbr":"","def":"물보라가 아니라 덩어리째 갑판 위로 올라오는 바닷물. 해치 커버·의장품 손상의 원인이다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"파라메트릭 롤","en":"Parametric rolling","abbr":"","def":"파정·파저가 선체를 지나며 GM이 주기적으로 변할 때 조우 주기가 롤 주기의 절반이면 롤이 증폭되는 현상. 선수·선미 방향 파에서 생긴다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"빌지 킬","en":"Bilge keel","abbr":"","def":"빌지 바깥에 길이 방향으로 붙인 좁은 판. 물을 휘저어 와류를 만들어 롤 감쇠를 늘리는 가장 간단한 장치다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"핀 안정기","en":"Fin stabilizer","abbr":"","def":"선측 밖으로 내민 날개의 받음각을 롤에 맞춰 바꿔 반대 모멘트를 만드는 장치. 속도가 있어야 효과가 있다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"안티롤 탱크","en":"Anti-roll tank","abbr":"ART","def":"좌우 탱크를 잇는 U자 관 속 물이 롤보다 위상이 늦게 오가며 반대 모멘트를 만드는 장치. 정지 상태에서도 작동한다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"프로펠러 레이싱","en":"Propeller racing","abbr":"","def":"큰 피칭으로 프로펠러가 수면 가까이 나오면 부하가 갑자기 줄어 회전수가 치솟는 현상. 엔진 조속기가 막아야 한다.","chapters":["seakeeping"],"category":"W"},
    {"ko":"타","en":"Rudder","abbr":"","def":"프로펠러 뒤에 단 날개. 타각을 주면 양력이 생겨 선미를 옆으로 밀고, 그 모멘트로 배가 방향을 바꾼다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"타각","en":"Rudder angle","abbr":"δ","def":"타가 중심선과 이루는 각. 상선은 보통 최대 ±35°까지 쓴다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"노모토 모델","en":"Nomoto model","abbr":"K, T","def":"타각에 대한 선회 각속도 응답을 1차 지연 Tṙ + r = Kδ로 근사한 모델. K는 선회성, T는 추종성(응답 지연)을 나타낸다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"선회권","en":"Turning circle","abbr":"","def":"일정한 타각으로 계속 돌 때 배가 그리는 궤적. 대형 상선은 전타 시 정상 선회 직경이 대략 선장의 3~4배다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"전진거리","en":"Advance","abbr":"","def":"타를 쓴 지점부터 선수 방향이 90° 바뀔 때까지 원래 침로 방향으로 나아간 거리. IMO 기준은 4.5 L 이하다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"횡거","en":"Transfer","abbr":"","def":"선수 방향이 90° 바뀔 때까지 원래 침로에서 옆으로 벗어난 거리.","chapters":["maneuvering"],"category":"M"},
    {"ko":"전술 직경","en":"Tactical diameter","abbr":"","def":"선수 방향이 180° 바뀔 때까지 원래 침로에서 옆으로 벗어난 거리. IMO 기준은 5 L 이하다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"지그재그 시험","en":"Zig-zag test","abbr":"","def":"선수 방향이 정해진 각도만큼 바뀔 때마다 타를 반대로 쓰는 시험. 오버슈트각으로 추종성과 침로 안정성을 평가한다(예: 10°/10°).","chapters":["maneuvering"],"category":"M"},
    {"ko":"오버슈트각","en":"Overshoot angle","abbr":"","def":"지그재그 시험에서 타를 반대로 쓴 뒤에도 선수가 계속 돌아간 각도. 클수록 배가 굼뜨게 반응한다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"크래시 스톱","en":"Crash stop","abbr":"","def":"전속 전진 중 전속 후진을 걸어 멈추는 시험. 정지 거리는 대형선에서 대략 선장의 10~15배에 이른다(IMO 기준 15 L).","chapters":["maneuvering"],"category":"M"},
    {"ko":"스쿼트","en":"Squat","abbr":"","def":"천수에서 항행할 때 선체 주변 유속 증가로 압력이 떨어져 배가 가라앉고 트림이 바뀌는 현상. 대략 속도의 제곱에 비례한다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"뱅크 효과","en":"Bank effect","abbr":"","def":"수로 벽에 가까이 붙어 항행할 때 선미가 벽 쪽으로 빨려 들고 선수가 밀려나는 현상.","chapters":["maneuvering"],"category":"M"},
    {"ko":"천수 효과","en":"Shallow water effect","abbr":"","def":"수심이 흘수의 몇 배 이내로 얕아지면 저항이 늘고 선회 직경이 커지며 스쿼트가 생기는 현상의 총칭.","chapters":["maneuvering"],"category":"M"},
    {"ko":"선수 스러스터","en":"Bow thruster","abbr":"","def":"선수 쪽 가로 터널 안에 둔 프로펠러. 저속에서 선수를 옆으로 밀어 접안·이안을 돕는다. 속도가 몇 노트만 넘어도 효과가 급감한다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"피벗 포인트","en":"Pivot point","abbr":"","def":"선회 중인 배에서 옆 방향 속도가 0인 점. 전진 선회 시 선수에서 약 1/4~1/3 L 지점에 있어 선미가 크게 바깥으로 쓸려 나간다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"프로펠러 횡압력","en":"Paddle-wheel effect (transverse thrust)","abbr":"","def":"단일 프로펠러 회전 때문에 선미가 한쪽으로 밀리는 효과. 우회전 프로펠러 배는 후진 시 선미가 좌현 쪽으로 간다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"앵커","en":"Anchor","abbr":"","def":"해저에 박혀 배를 붙잡는 기구. 실제 파지력의 대부분은 해저에 누운 앵커 체인의 무게와 마찰에서 나온다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"카테너리","en":"Catenary","abbr":"","def":"자기 무게로 늘어진 체인이 이루는 곡선. 늘어진 부분이 완충 역할을 해 앵커에 수평 하중만 걸리게 한다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"섀클","en":"Shackle","abbr":"","def":"앵커 체인의 길이 단위로, 1섀클은 15패덤(약 27.4 m)이다. 체인 연결용 U자 고리를 가리키기도 한다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"계류","en":"Mooring","abbr":"","def":"배를 부두나 부표에 줄로 묶어 두는 것. 선수줄·선미줄·브레스트 라인·스프링 라인으로 각 방향 움직임을 잡는다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"예인선","en":"Tug","abbr":"","def":"큰 배를 밀고 끌어 항만 안 조종을 돕는 작고 강력한 배. 능력을 볼라드 풀(정지 견인력, t)로 나타낸다.","chapters":["maneuvering"],"category":"M"},
    {"ko":"호깅","en":"Hogging","abbr":"","def":"선체 중앙이 들리고 양끝이 처지는 굽힘. 중앙이 파정에 놓일 때 생기며 갑판에 인장, 선저에 압축 응력이 걸린다.","chapters":["structure"],"category":"D"},
    {"ko":"새깅","en":"Sagging","abbr":"","def":"선체 중앙이 처지고 양끝이 들리는 굽힘. 중앙이 파저에 놓일 때 생기며 갑판에 압축 응력이 걸려 좌굴을 검토해야 한다.","chapters":["structure"],"category":"D"},
    {"ko":"종강도","en":"Longitudinal strength","abbr":"","def":"선체 전체를 하나의 보로 보고 길이 방향 굽힘·전단에 견디는 강도.","chapters":["structure"],"category":"D"},
    {"ko":"횡강도","en":"Transverse strength","abbr":"","def":"수압·화물 하중으로 단면이 찌그러지는 것에 견디는 강도. 늑골·특설 늑골·격벽이 맡는다.","chapters":["structure"],"category":"D"},
    {"ko":"정수 중 굽힘 모멘트","en":"Still water bending moment","abbr":"SWBM","def":"잔잔한 물에서 무게와 부력의 길이 방향 분포 차이로 생기는 굽힘 모멘트. 적재 계획으로 조절할 수 있다.","chapters":["structure"],"category":"D"},
    {"ko":"파랑 굽힘 모멘트","en":"Wave bending moment","abbr":"VWBM","def":"파 속에서 부력 분포가 변해 추가로 생기는 굽힘 모멘트. 선급 규칙이 선박 크기별 설계값을 준다.","chapters":["structure"],"category":"D"},
    {"ko":"전단력 선도","en":"Shear force diagram","abbr":"","def":"길이 방향 각 위치에서 한쪽 끝부터 누적한 (부력 − 무게)를 그린 선도. 적분하면 굽힘 모멘트 선도가 된다.","chapters":["structure"],"category":"D"},
    {"ko":"단면 계수","en":"Section modulus","abbr":"Z","def":"Z = I/y. 굽힘 응력 σ = M/Z이므로 클수록 같은 모멘트에서 응력이 작다. 갑판과 선저 위치에서 각각 계산한다.","chapters":["structure"],"category":"D"},
    {"ko":"중립축","en":"Neutral axis","abbr":"","def":"굽힘에서 응력이 0인 단면 높이. 단면 도심을 지나며 보통 형심의 40~45 % 높이에 있다.","chapters":["structure"],"category":"D"},
    {"ko":"단면 2차 모멘트","en":"Second moment of area","abbr":"I","def":"중립축에서 먼 재료일수록 제곱으로 크게 기여하는 굽힘 강성의 척도. 갑판·선저 판이 대부분을 차지한다.","chapters":["structure"],"category":"D"},
    {"ko":"종늑골식","en":"Longitudinal framing","abbr":"","def":"보강재를 길이 방향으로 촘촘히 두고 큰 횡 특설재로 받치는 방식. 종강도에 효율적이어서 대형 탱커·벌크선에 쓴다.","chapters":["structure"],"category":"D"},
    {"ko":"횡늑골식","en":"Transverse framing","abbr":"","def":"늑골을 가로 방향으로 촘촘히 두는 방식. 작은 배와 국부 하중이 큰 곳에 쓴다.","chapters":["structure"],"category":"D"},
    {"ko":"좌굴","en":"Buckling","abbr":"","def":"압축을 받는 얇은 판이나 보강재가 항복 전에 옆으로 휘어 버리는 불안정. 갑판·선저 판의 두께와 보강 간격을 정한다.","chapters":["structure"],"category":"D"},
    {"ko":"S–N 곡선","en":"S–N curve","abbr":"","def":"반복 응력 범위 S와 파손까지의 반복 횟수 N의 관계. 용접 이음의 상세 등급별로 다르다.","chapters":["structure"],"category":"D"},
    {"ko":"마이너 법칙","en":"Miner's rule","abbr":"","def":"여러 크기의 반복 응력이 섞일 때 각 응력의 (반복 수/허용 반복 수)를 더해 1이 되면 피로 파손으로 보는 누적 손상 법칙.","chapters":["structure"],"category":"D"},
    {"ko":"피로","en":"Fatigue","abbr":"","def":"항복보다 낮은 응력이 수백만 번 반복되며 균열이 자라는 파손. 파도 때문에 선체는 25년간 약 10⁸번 휘어진다.","chapters":["structure"],"category":"D"},
    {"ko":"휘핑","en":"Whipping","abbr":"","def":"슬래밍 충격으로 선체 전체가 2절점 고유 진동수로 떨리는 과도 진동. 굽힘 모멘트를 순간적으로 키운다.","chapters":["structure"],"category":"D"},
    {"ko":"스프링잉","en":"Springing","abbr":"","def":"파의 주파수 성분이 선체의 고유 진동수와 맞아 지속적으로 생기는 공진 진동. 대형 유연 선체에서 피로를 키운다.","chapters":["structure"],"category":"D"},
    {"ko":"설계 나선","en":"Design spiral","abbr":"","def":"주요 치수, 선형, 배치, 중량, 복원성, 동력, 구조, 비용을 차례로 검토하며 반복해 해에 수렴해 가는 설계 과정을 그린 그림.","chapters":["design"],"category":"D"},
    {"ko":"주요 치수","en":"Principal dimensions","abbr":"","def":"L, B, D, T, Cb, 속도 등 배의 크기와 형상을 정하는 기본 값. 화물량·항로·항만 제약에서 출발해 정한다.","chapters":["design"],"category":"D"},
    {"ko":"선도","en":"Lines plan","abbr":"","def":"선체 형상을 정면도(body plan), 측면도(sheer plan), 반폭도(half-breadth plan)의 세 방향 단면선으로 나타낸 도면.","chapters":["design"],"category":"D"},
    {"ko":"일반 배치","en":"General arrangement","abbr":"GA","def":"화물창, 기관실, 거주구, 탱크, 갑판 장비의 위치를 한눈에 보여 주는 도면.","chapters":["design"],"category":"D"},
    {"ko":"중량 추정","en":"Weight estimation","abbr":"","def":"설계 초기에 강재·의장·기관 중량과 무게중심을 경험식과 유사선 자료로 추정하는 일. DWT와 복원성을 확인하는 출발점이다.","chapters":["design"],"category":"D"},
    {"ko":"선급","en":"Classification society","abbr":"","def":"선체·기관의 기술 규칙을 만들고 설계 승인과 검사로 적합성을 인증하는 기관. 선급 증서는 보험과 등록의 전제다.","chapters":["design"],"category":"D"},
    {"ko":"국제선급연합회","en":"International Association of Classification Societies","abbr":"IACS","def":"주요 선급들의 협의체. 통일 규칙(UR)과 공통 구조 규칙(CSR)을 만든다.","chapters":["design"],"category":"D"},
    {"ko":"공통 구조 규칙","en":"Common Structural Rules","abbr":"CSR","def":"IACS 회원 선급이 벌크선과 유조선에 공통으로 적용하는 구조 규칙.","chapters":["design"],"category":"D"},
    {"ko":"블록 공법","en":"Block construction","abbr":"","def":"선체를 수백 톤짜리 블록으로 나눠 공장에서 따로 만들고 도크에서 이어 붙이는 건조 방식.","chapters":["building"],"category":"D"},
    {"ko":"탑재","en":"Erection","abbr":"","def":"완성된 블록을 크레인으로 도크에 올려 정위치에 맞추고 용접해 잇는 공정.","chapters":["building"],"category":"D"},
    {"ko":"진수","en":"Launching","abbr":"","def":"건조한 선체를 처음 물에 띄우는 일. 경사 선대에서 미끄러뜨리거나 도크에 물을 채우거나 플로팅 도크를 가라앉혀 띄운다.","chapters":["building"],"category":"D"},
    {"ko":"의장","en":"Outfitting","abbr":"","def":"선체에 기관·배관·전선·거주 설비·갑판 장비 등을 설치하는 모든 작업.","chapters":["building"],"category":"D"},
    {"ko":"선행 의장","en":"Advanced outfitting","abbr":"","def":"배관·전선·기기 등을 블록 단계에서 미리 설치하는 것. 도크·안벽 작업보다 쉽고 빠르다.","chapters":["building"],"category":"D"},
    {"ko":"건조막 두께","en":"Dry film thickness","abbr":"DFT","def":"도료가 마른 뒤의 도막 두께(µm). 방식 성능의 기준이며 밸러스트 탱크는 PSPC 규정으로 관리한다.","chapters":["building"],"category":"D"},
    {"ko":"네스팅","en":"Nesting","abbr":"","def":"강판 한 장 위에 절단할 부재들을 퍼즐처럼 배치해 버리는 부분을 최소화하는 일.","chapters":["building"],"category":"D"},
    {"ko":"도크","en":"Dock (dry dock)","abbr":"","def":"배를 짓거나 수리하려고 물을 빼고 넣을 수 있게 만든 거대한 구덩이. 조선소 생산 능력의 병목이다.","chapters":["building"],"category":"D"},
    {"ko":"시운전","en":"Sea trial","abbr":"","def":"인도 전에 바다에서 속도·출력, 조종성, 정지, 진동, 장비 성능을 확인하는 시험.","chapters":["building"],"category":"D"},
    {"ko":"TEU","en":"Twenty-foot equivalent unit","abbr":"TEU","def":"20 ft 컨테이너 1개를 기준으로 한 적재 용량 단위. 40 ft 컨테이너(FEU)는 2 TEU로 센다.","chapters":["cargo"],"category":"C"},
    {"ko":"래싱","en":"Lashing","abbr":"","def":"갑판 위 컨테이너를 래싱 바·턴버클·트위스트 록으로 고정하는 일. 롤 가속도가 큰 짧은 주기 횡동요에서 하중이 크다.","chapters":["cargo"],"category":"C"},
    {"ko":"베이 플랜","en":"Bay plan","abbr":"","def":"컨테이너선의 각 베이(길이 방향 위치)·열·단에 어떤 컨테이너를 실었는지 보여 주는 적재도.","chapters":["cargo"],"category":"C"},
    {"ko":"셀 가이드","en":"Cell guide","abbr":"","def":"화물창 안에서 컨테이너를 수직으로 안내하는 철제 레일. 창 안의 컨테이너는 래싱 없이 고정된다.","chapters":["cargo"],"category":"C"},
    {"ko":"해치 커버","en":"Hatch cover","abbr":"","def":"화물창 개구부를 덮는 수밀 덮개. 컨테이너선에서는 그 위에도 컨테이너를 쌓는다.","chapters":["cargo"],"category":"C"},
    {"ko":"교호 적재","en":"Alternate hold loading","abbr":"","def":"벌크선에서 무거운 화물(철광석 등)을 한 창 걸러 하나씩 싣는 방식. 무게중심을 올려 GM을 줄이지만 구조에 큰 국부 하중을 준다.","chapters":["cargo"],"category":"C"},
    {"ko":"액상화","en":"Cargo liquefaction","abbr":"","def":"수분이 많은 정광·니켈 광석 등이 진동으로 진흙처럼 흐르게 되는 현상. 화물이 한쪽으로 쏠려 전복을 일으킬 수 있다.","chapters":["cargo"],"category":"C"},
    {"ko":"불활성 가스","en":"Inert gas","abbr":"IG","def":"산소 농도를 8 % 이하로 낮춘 배기가스나 질소. 유조선 화물창에 채워 폭발 분위기가 생기지 않게 한다.","chapters":["cargo"],"category":"C"},
    {"ko":"원유 세정","en":"Crude oil washing","abbr":"COW","def":"하역 중 화물인 원유 자체를 고압으로 분사해 탱크 벽의 잔류물을 씻어 내는 방법.","chapters":["cargo"],"category":"C"},
    {"ko":"멤브레인형 탱크","en":"Membrane tank","abbr":"","def":"선체 안쪽에 단열재와 얇은 금속 막(스테인리스·인바)을 붙인 LNG 화물창. 선체 공간을 효율적으로 쓴다.","chapters":["cargo"],"category":"C"},
    {"ko":"모스형 탱크","en":"Moss-type (spherical) tank","abbr":"","def":"자립형 알루미늄 구형 탱크를 갑판 위로 반쯤 드러나게 실은 LNG 화물창. 슬로싱에 강하다.","chapters":["cargo"],"category":"C"},
    {"ko":"증발 가스","en":"Boil-off gas","abbr":"BOG","def":"약 −162 °C의 LNG에 열이 들어와 증발한 가스. 엔진 연료로 쓰거나 재액화하고 남으면 GCU에서 태운다.","chapters":["cargo"],"category":"C"},
    {"ko":"슬로싱","en":"Sloshing","abbr":"","def":"부분 적재 탱크 안 액체가 출렁이며 벽을 때리는 현상. LNG 멤브레인 탱크의 충전률 제한 이유다.","chapters":["cargo"],"category":"C"},
    {"ko":"자동차 운반선","en":"Pure car and truck carrier","abbr":"PCTC","def":"여러 층의 갑판에 자동차를 몰고 들어가 싣는 배. 갑판이 높고 바람 받는 면적이 커 복원성과 조종에 주의한다.","chapters":["cargo"],"category":"C"},
    {"ko":"로로선","en":"Ro-Ro ship","abbr":"","def":"차량이 램프로 직접 굴러 타고 내리는 배. 넓은 차량 갑판의 침수가 순식간에 복원성을 잃게 할 수 있다.","chapters":["cargo"],"category":"C"},
    {"ko":"파나막스","en":"Panamax","abbr":"","def":"옛 파나마 운하 갑문을 통과할 수 있는 최대 크기(폭 약 32.3 m). 2016년 확장 이후 기준은 네오파나막스(폭 약 51 m)다.","chapters":["cargo"],"category":"C"},
    {"ko":"케이프사이즈","en":"Capesize","abbr":"","def":"수에즈·파나마 운하를 지나지 못해 희망봉·케이프혼을 돌아가는 대형 벌크선. 대표적으로 15만~20만 DWT다.","chapters":["cargo"],"category":"C"},
    {"ko":"초대형 원유 운반선","en":"Very large crude carrier","abbr":"VLCC","def":"대략 20만~32만 DWT의 원유 운반선. 약 200만 배럴을 싣는다.","chapters":["cargo"],"category":"C"},
    {"ko":"활주선","en":"Planing hull","abbr":"","def":"고속에서 선저의 동적 양력이 무게 대부분을 받쳐 선체가 떠올라 미끄러지듯 달리는 배.","chapters":["special"],"category":"C"},
    {"ko":"수중익선","en":"Hydrofoil craft","abbr":"","def":"선체 아래 수중 날개의 양력으로 선체를 물 위로 들어 올려 저항을 줄이는 고속선.","chapters":["special"],"category":"C"},
    {"ko":"쌍동선","en":"Catamaran","abbr":"","def":"가늘고 긴 두 선체를 갑판으로 이은 배. 넓은 갑판과 큰 횡복원성을 갖고 고속에서 조파 저항이 작다.","chapters":["special"],"category":"C"},
    {"ko":"표면 효과선","en":"Surface effect ship","abbr":"SES","def":"쌍동선 두 선체 사이를 앞뒤 스커트로 막고 공기 쿠션을 불어넣어 무게 일부를 받치는 고속선.","chapters":["special"],"category":"C"},
    {"ko":"쇄빙선","en":"Icebreaker","abbr":"","def":"경사진 선수로 얼음 위에 올라타 무게로 깨며 나아가는 배. 두꺼운 외판과 큰 출력, 횡동요 탱크를 갖춘다.","chapters":["special"],"category":"C"},
    {"ko":"주 밸러스트 탱크","en":"Main ballast tank (submarine)","abbr":"MBT","def":"잠수함 외곽의 큰 탱크. 해수를 채우면 잠항하고 압축 공기로 해수를 밀어내면 부상한다.","chapters":["special"],"category":"C"},
    {"ko":"FPSO","en":"Floating production, storage and offloading unit","abbr":"FPSO","def":"해저 유전의 원유를 받아 처리·저장했다가 셔틀 탱커로 넘기는 부유식 해양 설비. 터릿으로 계류해 바람에 따라 돈다.","chapters":["special"],"category":"C"},
    {"ko":"반잠수식","en":"Semi-submersible","abbr":"","def":"물속 깊은 폰툰과 가는 기둥으로 갑판을 받친 해양 구조물. 수선면이 작아 파랑 운동이 작다.","chapters":["special"],"category":"C"},
    {"ko":"잭업","en":"Jack-up rig","abbr":"","def":"다리를 해저까지 내려 선체를 물 위로 들어 올리는 해양 설비. 얕은 바다의 시추·해상 풍력 설치에 쓴다.","chapters":["special"],"category":"C"},
    {"ko":"주 배전반","en":"Main switchboard","abbr":"MSB","def":"발전기 전력을 모아 각 부하로 나누는 배전반. 보통 두 구역으로 나눠 버스 타이로 연결한다.","chapters":["electric"],"category":"G"},
    {"ko":"동기 투입","en":"Synchronizing","abbr":"","def":"운전 중인 모선에 발전기를 병렬 연결하기 전에 전압·주파수·위상을 맞추는 과정.","chapters":["electric"],"category":"G"},
    {"ko":"드룹","en":"Droop","abbr":"","def":"부하가 늘면 속도(주파수)나 전압이 조금 떨어지도록 한 조속기·AVR 특성. 병렬 발전기의 부하 분담을 안정시킨다.","chapters":["electric"],"category":"G"},
    {"ko":"전력 관리 시스템","en":"Power management system","abbr":"PMS","def":"부하에 따라 발전기를 자동으로 기동·정지하고 부하를 분담시키며, 과부하 시 덜 중요한 부하를 차단하는 시스템.","chapters":["electric"],"category":"G"},
    {"ko":"블랙아웃","en":"Blackout","abbr":"","def":"주 전원이 모두 끊긴 상태. 추진·조타를 잃어 매우 위험하므로 비상 발전기가 45초 안에 자동 기동해야 한다.","chapters":["electric"],"category":"G"},
    {"ko":"비상 발전기","en":"Emergency generator","abbr":"EG","def":"주 전원 상실 시 조명·조타·통신·소화 펌프 등 필수 부하에 전력을 주는 발전기. 격벽 갑판 위 별도 공간에 둔다.","chapters":["electric"],"category":"G"},
    {"ko":"디젤–전기 추진","en":"Diesel–electric propulsion","abbr":"","def":"디젤 발전기로 전기를 만들어 전동기로 프로펠러를 돌리는 방식. 크루즈·쇄빙선·DP 선박에 많다.","chapters":["electric"],"category":"G"},
    {"ko":"축발전기","en":"Shaft generator","abbr":"","def":"주기관 축에서 동력을 빼내 전기를 만드는 발전기. 효율 좋은 주기관 연료로 선내 전력을 만든다.","chapters":["electric"],"category":"G"},
    {"ko":"PTO/PTI","en":"Power take-off / power take-in","abbr":"PTO/PTI","def":"축에 붙은 전기 기계를 발전기(PTO)로도, 추진 보조 모터(PTI)로도 쓰는 하이브리드 방식.","chapters":["electric"],"category":"G"},
    {"ko":"배터리 하이브리드","en":"Battery hybrid","abbr":"","def":"발전기에 배터리를 더한 전력 계통. 순간 부하를 배터리가 받아 발전기를 효율 좋은 부하에서만 돌린다.","chapters":["electric"],"category":"G"},
    {"ko":"피크 쉐이빙","en":"Peak shaving","abbr":"","def":"크레인·스러스터 등의 순간 최대 부하를 배터리가 대신 공급해 발전기 대수와 부하 변동을 줄이는 운전.","chapters":["electric"],"category":"G"},
    {"ko":"육상 전원 공급","en":"Alternative maritime power (shore power)","abbr":"AMP","def":"정박 중 발전기를 끄고 부두의 전력을 받아 쓰는 것. 항만의 배출가스와 소음을 줄인다.","chapters":["electric"],"category":"G"},
    {"ko":"에너지 효율 설계 지수","en":"Energy Efficiency Design Index","abbr":"EEDI","def":"신조선의 설계상 CO₂ 배출(g)을 수송 능력(용량 × 속도)으로 나눈 값. 기준선 대비 단계적으로 강화된다.","chapters":["green"],"category":"G"},
    {"ko":"현존선 에너지 효율 지수","en":"Energy Efficiency Existing Ship Index","abbr":"EEXI","def":"이미 운항 중인 배에 EEDI와 같은 방식으로 계산해 적용하는 설계 지표. 주로 엔진 출력 제한으로 맞춘다.","chapters":["green"],"category":"G"},
    {"ko":"탄소 집약도 지표","en":"Carbon Intensity Indicator","abbr":"CII","def":"운항선이 1년간 배출한 CO₂를 수송 실적(용량 × 거리)으로 나눈 값. A~E 등급으로 평가한다.","chapters":["green"],"category":"G"},
    {"ko":"선박 에너지 효율 관리 계획","en":"Ship Energy Efficiency Management Plan","abbr":"SEEMP","def":"배마다 비치하는 에너지 효율 개선 계획서. CII 개선 조치를 여기에 담는다.","chapters":["green"],"category":"G"},
    {"ko":"감속 운항","en":"Slow steaming","abbr":"","def":"설계 속도보다 느리게 달려 연료를 아끼는 운항. 거리당 연료는 대략 속도의 제곱에 비례해 줄어든다.","chapters":["green"],"category":"G"},
    {"ko":"로터 세일","en":"Rotor sail (Flettner rotor)","abbr":"","def":"갑판 위 원통을 회전시켜 바람 속에서 마그누스 효과로 추력을 얻는 풍력 보조 장치.","chapters":["green"],"category":"G"},
    {"ko":"공기 윤활","en":"Air lubrication","abbr":"","def":"선저에 공기 거품이나 막을 깔아 물과 닿는 면적을 줄여 마찰 저항을 줄이는 기술. 대표적으로 수 % 절감한다.","chapters":["green"],"category":"G"},
    {"ko":"Well-to-Wake","en":"Well-to-wake","abbr":"WtW","def":"연료의 생산·운송 단계(well-to-tank)부터 선박에서 태우는 단계(tank-to-wake)까지 전 과정의 온실가스 배출.","chapters":["green"],"category":"G"},
    {"ko":"Tank-to-Wake","en":"Tank-to-wake","abbr":"TtW","def":"선박에서 연료를 태울 때 직접 나오는 배출만 센 것. 수소·암모니아는 0에 가깝지만 생산 방식에 따라 WtW는 클 수 있다.","chapters":["green"],"category":"G"},
    {"ko":"배출규제해역","en":"Emission Control Area","abbr":"ECA","def":"SOx는 0.10 %, NOx는 Tier III 등 더 엄격한 배출 기준이 적용되는 해역. 북해·발트해·북미 연안 등이 있다.","chapters":["green"],"category":"G"},
    {"ko":"IMO 2020 황 상한","en":"IMO 2020 global sulphur cap","abbr":"","def":"2020년부터 전 세계 선박 연료의 황 함량을 0.50 % 이하로 제한한 MARPOL 부속서 VI 규정.","chapters":["green"],"category":"G"},
    {"ko":"암모니아 연료","en":"Ammonia fuel","abbr":"NH₃","def":"탄소가 없어 연소 시 CO₂를 내지 않는 연료. 독성이 강하고 연소가 느리며 N₂O·NOx 관리가 과제다.","chapters":["green"],"category":"G"},
    {"ko":"메탄올 연료","en":"Methanol fuel","abbr":"","def":"상온에서 액체라 저장이 쉬운 대체 연료. 바이오·e-메탄올이면 전 과정 배출을 크게 줄일 수 있다.","chapters":["green"],"category":"G"},
    {"ko":"위도","en":"Latitude","abbr":"φ","def":"적도에서 남북으로 잰 각도(0~90°). 위도 1분의 자오선 길이가 1해리다.","chapters":["navigation"],"category":"N"},
    {"ko":"경도","en":"Longitude","abbr":"λ","def":"본초 자오선에서 동서로 잰 각도(0~180°). 경도 1분의 길이는 cos(위도) 배로 줄어든다.","chapters":["navigation"],"category":"N"},
    {"ko":"항정선","en":"Rhumb line (loxodrome)","abbr":"","def":"모든 자오선과 같은 각도로 만나는 경로. 침로를 일정하게 유지하면 따라가게 되며 메르카토르 해도에서 직선이다.","chapters":["navigation"],"category":"N"},
    {"ko":"대권","en":"Great circle","abbr":"","def":"지구 중심을 지나는 평면이 지구 표면과 만나는 원. 두 지점 사이의 최단 경로이며 침로가 계속 바뀐다.","chapters":["navigation"],"category":"N"},
    {"ko":"메르카토르 도법","en":"Mercator projection","abbr":"","def":"고위도로 갈수록 남북 방향을 늘려 각도를 보존하는 원통 도법. 항정선이 직선이 되어 해도의 표준이 되었다.","chapters":["navigation"],"category":"N"},
    {"ko":"추측 항법","en":"Dead reckoning","abbr":"DR","def":"알고 있는 출발 위치에 침로와 속력, 경과 시간을 더해 현재 위치를 추정하는 방법. 시간이 지날수록 오차가 쌓인다.","chapters":["navigation"],"category":"N"},
    {"ko":"침로","en":"Course","abbr":"Co","def":"배가 나아가려는 방향을 북쪽에서 시계 방향으로 잰 각(000°~359°).","chapters":["navigation"],"category":"N"},
    {"ko":"방위","en":"Bearing","abbr":"Brg","def":"자선에서 본 물표의 방향. 진북 기준 진방위와 선수 기준 상대 방위가 있다.","chapters":["navigation"],"category":"N"},
    {"ko":"대수 속력과 대지 속력","en":"Speed through water / over ground","abbr":"STW / SOG","def":"물에 대한 속력(로그)과 땅에 대한 속력(GNSS). 차이는 조류 때문이다.","chapters":["navigation"],"category":"N"},
    {"ko":"편차","en":"Variation","abbr":"Var","def":"진북과 자북 사이의 각. 장소와 연도에 따라 다르며 해도의 나침도에 적혀 있다.","chapters":["navigation"],"category":"N"},
    {"ko":"자차","en":"Deviation","abbr":"Dev","def":"선내 철재·전기 장비 때문에 자기 컴퍼스가 자북에서 벗어나는 각. 선수 방향마다 달라 자차표로 관리한다.","chapters":["navigation"],"category":"N"},
    {"ko":"조류 보정","en":"Course to steer","abbr":"CTS","def":"조류의 방향(set)과 속도(drift)를 고려해 원하는 대지 항적을 따라가도록 정한 침로.","chapters":["navigation"],"category":"N"},
    {"ko":"위치선","en":"Line of position","abbr":"LOP","def":"한 번의 관측(방위, 거리, 천체 고도 등)으로 배가 그 위 어딘가에 있다고 알 수 있는 선. 둘 이상이 교차하면 위치가 된다.","chapters":["navigation"],"category":"N"},
    {"ko":"천측","en":"Celestial navigation","abbr":"","def":"육분의로 천체의 고도를 재고 정확한 시각과 천측력을 써서 위치선을 구하는 항법.","chapters":["navigation"],"category":"N"},
    {"ko":"조석","en":"Tide","abbr":"","def":"달과 태양의 인력으로 해수면이 주기적으로 오르내리는 현상. 대부분 해역에서 하루 두 번(약 12시간 25분 주기) 만조와 간조가 온다.","chapters":["navigation"],"category":"N"},
    {"ko":"12분의 1 법칙","en":"Rule of twelfths","abbr":"","def":"간조에서 만조까지 6시간 동안 조위가 시간마다 조차의 1, 2, 3, 3, 2, 1/12씩 오른다고 보는 근사법.","chapters":["navigation"],"category":"N"},
    {"ko":"해도 기준면","en":"Chart datum","abbr":"CD","def":"해도 수심의 기준이 되는 낮은 조위면(보통 최저 천문조 LAT). 실제 수심 = 해도 수심 + 조고.","chapters":["navigation"],"category":"N"},
    {"ko":"선저 여유 수심","en":"Under keel clearance","abbr":"UKC","def":"용골 아래와 해저 사이의 여유 깊이. 스쿼트·파랑 운동·조석 오차를 고려해 확보해야 한다.","chapters":["navigation"],"category":"N"},
    {"ko":"GNSS","en":"Global navigation satellite system","abbr":"GNSS","def":"GPS, GLONASS, Galileo, BeiDou 등 위성 측위 시스템의 총칭. 위성까지의 거리로 위치와 시각을 구한다.","chapters":["navigation"],"category":"N"},
    {"ko":"정밀도 저하율","en":"Dilution of precision","abbr":"DOP","def":"위성 배치가 위치 정확도를 얼마나 나쁘게 만드는지 나타내는 계수. 위성이 한쪽에 몰려 있으면 커진다.","chapters":["navigation"],"category":"N"},
    {"ko":"레이더","en":"Radar","abbr":"","def":"전파를 쏘아 반사파가 돌아오는 시간으로 거리를, 안테나 방향으로 방위를 재는 장비. 선박용은 X밴드(3 cm)와 S밴드(10 cm)를 쓴다.","chapters":["bridge"],"category":"N"},
    {"ko":"자동 레이더 플로팅 장치","en":"Automatic radar plotting aid","abbr":"ARPA","def":"레이더 물표를 자동 추적해 침로·속력과 CPA·TCPA를 계산해 주는 기능.","chapters":["bridge"],"category":"N"},
    {"ko":"최근접점","en":"Closest point of approach","abbr":"CPA","def":"현재 침로·속력이 유지될 때 상대선과 가장 가까워지는 거리.","chapters":["bridge"],"category":"N"},
    {"ko":"최근접점 도달 시간","en":"Time to CPA","abbr":"TCPA","def":"최근접점에 이르기까지 남은 시간. 음수면 이미 지나간 것이다.","chapters":["bridge"],"category":"N"},
    {"ko":"선박 자동 식별 장치","en":"Automatic identification system","abbr":"AIS","def":"선명·위치·침로·속력 등을 VHF로 주기적으로 방송하고 받는 장치. 레이더가 못 보는 곳 너머의 배도 알 수 있다.","chapters":["bridge"],"category":"N"},
    {"ko":"전자 해도 표시 정보 시스템","en":"Electronic chart display and information system","abbr":"ECDIS","def":"공식 전자 해도(ENC)에 자선 위치·항로·레이더·AIS를 겹쳐 보여 주고 위험을 경고하는 항해 장비.","chapters":["bridge"],"category":"N"},
    {"ko":"국제 해상 충돌 예방 규칙","en":"COLREG","abbr":"COLREG","def":"1972년 협약의 해상 교통 규칙. 경계, 안전 속력, 마주침·횡단·추월 시의 행동, 등화와 형상물을 정한다.","chapters":["bridge"],"category":"N"},
    {"ko":"피항선","en":"Give-way vessel","abbr":"","def":"규칙상 다른 배의 진로를 피해야 하는 배. 일찍, 크게, 분명하게 동작해야 한다.","chapters":["bridge"],"category":"N"},
    {"ko":"유지선","en":"Stand-on vessel","abbr":"","def":"침로와 속력을 유지해야 하는 배. 피항선이 동작하지 않아 충돌 위험이 임박하면 스스로 피해야 한다.","chapters":["bridge"],"category":"N"},
    {"ko":"현등","en":"Sidelights","abbr":"","def":"우현 초록, 좌현 빨강 등. 정선수에서 각 현 정횡 뒤 22.5°까지(112.5°) 비춘다.","chapters":["bridge"],"category":"N"},
    {"ko":"마스트등","en":"Masthead light","abbr":"","def":"선수미선 위에 단 흰색 등. 정선수 좌우 112.5°씩, 모두 225°를 비춘다. 길이 50 m 이상 배는 앞뒤 두 개를 단다.","chapters":["bridge"],"category":"N"},
    {"ko":"선미등","en":"Sternlight","abbr":"","def":"선미에 단 흰색 등으로 뒤쪽 135°를 비춘다. 이것만 보이면 그 배를 추월하는 중이다.","chapters":["bridge"],"category":"N"},
    {"ko":"안전 속력","en":"Safe speed","abbr":"","def":"시정·교통량·조종 성능·해상 상태를 고려해 충돌을 피할 적절한 동작을 하고 정해진 거리 안에 멈출 수 있는 속력.","chapters":["bridge"],"category":"N"},
    {"ko":"자율운항선박","en":"Maritime autonomous surface ship","abbr":"MASS","def":"사람의 개입 없이 일부 또는 전부 스스로 운항하는 선박. IMO는 자동화·원격·완전 자율 정도로 4단계를 정의했다.","chapters":["autonomous"],"category":"N"},
    {"ko":"동적 위치 유지","en":"Dynamic positioning","abbr":"DP","def":"위치·방위 센서와 제어기, 스러스터로 바람·조류·파랑 표류력에 맞서 위치와 선수 방위를 자동 유지하는 시스템.","chapters":["autonomous"],"category":"N"},
    {"ko":"LOS 유도","en":"Line-of-sight guidance","abbr":"LOS","def":"경로 위 앞쪽 일정 거리(lookahead)의 점을 겨냥하도록 목표 침로를 정하는 경로 추종 법칙. 단순하고 견실하다.","chapters":["autonomous"],"category":"N"},
    {"ko":"속도 장애물","en":"Velocity obstacle","abbr":"VO","def":"상대선과 충돌하게 되는 자선 속도들의 집합. 그 밖의 속도를 고르면 직선 운동 가정에서 충돌하지 않는다.","chapters":["autonomous"],"category":"N"},
    {"ko":"칼만 필터","en":"Kalman filter","abbr":"KF","def":"운동 모델의 예측과 잡음 섞인 측정을 각각의 불확실성에 따라 가중 결합해 상태를 추정하는 재귀 필터.","chapters":["autonomous"],"category":"N"},
    {"ko":"센서 융합","en":"Sensor fusion","abbr":"","def":"레이더·AIS·카메라·라이다 등 여러 센서의 정보를 합쳐 하나의 일관된 주변 상황도를 만드는 일.","chapters":["autonomous"],"category":"N"},
    {"ko":"A* 경로 계획","en":"A* path planning","abbr":"A*","def":"격자 위에서 지나온 비용과 남은 거리 추정치를 더한 값이 작은 순서로 탐색해 최단 경로를 찾는 알고리즘.","chapters":["autonomous"],"category":"N"},
    {"ko":"원격 운항 센터","en":"Remote operation centre","abbr":"ROC","def":"육상에서 자율·원격 선박을 감시하고 필요하면 직접 조종하는 관제 시설.","chapters":["autonomous"],"category":"N"},
    {"ko":"선박 교통 관제","en":"Vessel traffic service","abbr":"VTS","def":"항만·좁은 수로에서 레이더와 AIS로 교통을 감시하고 정보·권고·지시를 주는 육상 서비스.","chapters":["bridge"],"category":"N"},
    {"ko":"재화중량","en":"Deadweight","abbr":"DWT","def":"만재흘수에서의 배수량에서 경하중량을 뺀 값. 화물·연료·청수·선원·식량 등 배가 실을 수 있는 총질량(t)이다.","chapters":["buoyancy"],"category":"H"},
    {"ko":"총톤수","en":"Gross tonnage","abbr":"GT","def":"선체 내부 폐위 용적 V로 GT = (0.2 + 0.02·log₁₀V)·V로 계산하는 무차원 크기. 등록·수수료·규칙 적용 기준이다.","chapters":["buoyancy"],"category":"H"},
    {"ko":"순톤수","en":"Net tonnage","abbr":"NT","def":"화물·여객 공간의 용적으로 계산하는 무차원 크기. 항만 이용료와 운하 통항료의 기준이 되며 GT의 30 % 아래로는 내려가지 않는다.","chapters":["buoyancy"],"category":"H"},
    {"ko":"노트","en":"Knot","abbr":"kn","def":"1시간에 1해리를 가는 속도. 1 kn = 1.852 km/h ≈ 0.5144 m/s.","chapters":["navigation"],"category":"H"},
    {"ko":"해리","en":"Nautical mile","abbr":"nm","def":"위도 1분의 평균 길이에서 나온 거리 단위. 1 nm = 1,852 m.","chapters":["navigation"],"category":"H"},
    {"ko":"국제해사기구","en":"International Maritime Organization","abbr":"IMO","def":"해상 안전과 해양 오염 방지를 다루는 UN 전문 기구. SOLAS·MARPOL·COLREG 등 협약을 관리한다.","chapters":["green"],"category":"H"},
    {"ko":"해상 인명 안전 협약","en":"International Convention for the Safety of Life at Sea","abbr":"SOLAS","def":"타이타닉 침몰을 계기로 시작된 선박 안전의 기본 협약. 구획·복원성, 소방, 구명 설비, 항해 안전을 정한다.","chapters":["damage"],"category":"H"},
    {"ko":"해양 오염 방지 협약","en":"MARPOL","abbr":"MARPOL","def":"선박에 의한 기름·유해 액체·오수·쓰레기·대기 오염을 규제하는 협약. 부속서 VI가 대기 오염과 에너지 효율을 다룬다.","chapters":["green"],"category":"H"},
    {"ko":"만재흘수선 협약","en":"International Convention on Load Lines","abbr":"ICLL","def":"선박의 최소 건현과 만재흘수선 표시를 정한 1966년 협약.","chapters":["buoyancy"],"category":"H"},
    {"ko":"톤수 측정 협약","en":"International Convention on Tonnage Measurement of Ships","abbr":"ITC 1969","def":"GT·NT를 폐위 용적 기반으로 계산하는 국제 공통 방법을 정한 협약.","chapters":["buoyancy"],"category":"H"},
    {"ko":"기국","en":"Flag state","abbr":"","def":"배가 등록되어 국기를 다는 나라. 그 배에 대한 협약 이행과 검사의 1차 책임을 진다.","chapters":["design"],"category":"H"},
    {"ko":"항만국 통제","en":"Port state control","abbr":"PSC","def":"입항한 외국 선박이 국제 협약에 맞는지 항만국이 점검하고 결함이 크면 출항을 정지시키는 제도.","chapters":["design"],"category":"H"},
    {"ko":"정기선과 부정기선","en":"Liner / tramp shipping","abbr":"","def":"정해진 항로·일정으로 다니는 정기선(주로 컨테이너선)과 화물이 있는 곳으로 가는 부정기선(벌크선·탱커).","chapters":["cargo"],"category":"H"},
    {"ko":"용선","en":"Chartering","abbr":"","def":"배를 빌리는 계약. 한 항차(항해 용선), 기간(정기 용선), 선원 없이 배만(나용선) 빌리는 형태가 있다.","chapters":["cargo"],"category":"H"},
    {"ko":"보퍼트 풍력 계급","en":"Beaufort scale","abbr":"","def":"풍속을 해면 모습에 따라 0(고요)~12(싹쓸바람)로 나눈 등급.","chapters":["waves"],"category":"H"},
  ]
};
